import{_ as t,o as r,c as s,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator 2021-07-13","description":"","frontmatter":{"title":"Ceph Orchestrator 2021-07-13","date":"2021-07-13T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph Orchestrator","Kubernetes 集成","存储管理","Rook","本地存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_2021-07-13.md","filePath":"posts/2021/Ceph_Orchestrator_2021-07-13.md","lastUpdated":1780460162000}'),e={name:"posts/2021/Ceph_Orchestrator_2021-07-13.md"};function l(a,o,i,p,g,_){return r(),s("div",null,[...o[0]||(o[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph Orchestrator 会议</p><p><strong>日期：</strong> 2021年7月13日</p><p><strong>参会人员：</strong> [参会人员名单]</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>ISCSI 问题讨论：</strong></p><ul><li><strong>容器名称问题：</strong> 讨论了容器名称中包含点（dot）的问题，建议避免使用不含点的容器名称，因为这会导致 DNS 解析问题。</li><li><strong>Cgroups 共享问题：</strong> 讨论了容器和系统之间的 cgroups 不共享的问题，已有人贡献了解决方案并合并到 pacific 版本中。</li></ul></li><li><p><strong>LSO（Local Storage Operator）讨论：</strong></p><ul><li><strong>安装和支持问题：</strong> 讨论了 LSO 在 vanilla Kubernetes 环境中的安装和支持问题，目前 LSO 的 README 文件不够友好，需要澄清其在上游的支持情况。</li><li><strong>LSO 集成到 Rook 组织：</strong> 讨论了是否有可能将 LSO 集成到 Rook 的 GitHub 仓库中，LSO 团队对保持所有权感兴趣，因此可能不会接受这个提议。</li><li><strong>LSO 功能需求：</strong> 讨论了 LSO 的功能需求，包括硬件库存检查、动态 PV 分配、原始设备支持等，目前没有完全满足这些需求的存储运营商。</li><li><strong>Rook 本地存储运营商：</strong> 提出了创建一个新的 Rook 本地存储运营商的想法，以满足上述需求，并可能从 LSO 和 TopoLVM 中学习。</li></ul></li><li><p><strong>后续行动计划：</strong></p><ul><li><strong>基本支持实现：</strong> 计划在 Manager Rook 中实现基本支持，包括使用预创建的 PV 或 LSO，并支持基本的 OSD 创建和销毁。</li><li><strong>新运营商开发：</strong> 计划在基本支持实现后，开发一个新的、更强大的本地存储运营商。</li><li><strong>社区讨论：</strong> 将在即将举行的 Rook 社区会议上提出这些讨论点，以获取更多反馈和建议。</li></ul></li></ol><p><strong>决定事项：</strong></p><ul><li>避免使用不含点的容器名称。</li><li>继续推进 Manager Rook 的基本支持实现。</li><li>探索开发新的 Rook 本地存储运营商的可能性。</li></ul><p><strong>后续行动：</strong></p><ul><li>在 Rook 社区会议上提出讨论点。</li><li>继续推进 Manager Rook 的基本支持实现。</li><li>探索新的本地存储运营商的开发。</li></ul><p><strong>会议结束时间：</strong> [具体时间]</p><p><strong>下次会议时间：</strong> [具体时间]</p><p><strong>会议纪要编写人：</strong> [编写人姓名]</p><p><strong>会议纪要审核人：</strong> [审核人姓名]</p><p><strong>备注：</strong> 请参会人员确认会议纪要的准确性，并在确认无误后进行分发。</p>',15)])])}const h=t(e,[["render",l]]);export{u as __pageData,h as default};
